// ─── Core AI call ─────────────────────────────────────────────────────────────
//
// Pipeline order (guaranteed for BOTH Job Seeker and Recruiter flows):
//   1. normalizeResumeText()   — deterministic, no AI, cleans + structures raw text
//   2. prepareTextForPrompt()  — assembles labelled sections for AI injection
//   3. buildPrompt()           — injects prepared text into the master prompt
//   4. OpenAI gpt-4o call      — structured analysis via tool call
//   5. normalizeAnalysis()     — clamps/validates all AI output fields

export interface CallAnalysisOptions {
  resumeText: string;
  language: string;
  openAIApiKey: string;
  timeoutMs?: number;
}

export interface CallAnalysisResult {
  analysis: NormalizedAnalysis;
  /** Structured resume fields extracted deterministically before AI call. */
  normalizedInput: import("./resume-normalizer.ts").NormalizedResumeInput;
  /** Layer A scores — stable, code-driven, never overridden by AI. */
  deterministicScores: DeterministicScores;
}

export async function callAnalysisAI(opts: CallAnalysisOptions): Promise<CallAnalysisResult> {
  const { resumeText, language, openAIApiKey, timeoutMs = 170_000 } = opts;

  // ── Layer A: Deterministic normalization + ATS scoring (no AI) ─────────────
  const rawText = resumeText ?? "";
  let normalizedInput = normalizeResumeText(rawText);
  console.log("[analysis-core] rawText:", rawText);
  console.log("[analysis-core] normalizedInput:", JSON.stringify(normalizedInput));

  if (rawText.length > 200 && normalizedInput.skills.length < 3) {
    console.warn("[analysis-core] Weak skills extraction detected. Re-running normalizer fallback guard.");
    normalizedInput = normalizeResumeText(`${rawText}
${rawText}`);
    console.log("[analysis-core] normalizedInputAfterGuard:", JSON.stringify(normalizedInput));
  }

  const deterministicScores = computeAtsScores(normalizedInput, rawText);

  // ── Prepare cleaned text for AI prompt injection ────────────────────────────
  const preparedText = prepareTextForPrompt(normalizedInput);

  // ── Layer B: Build base prompt ─────────────────────────────────────────────
  const { systemPrompt, userPrompt } = buildPrompt(preparedText, language, deterministicScores);

  // ── Retry loop — max VALIDATION.MAX_ATTEMPTS total (including first call) ──
  // Attempt 1: base prompt.
  // Attempt 2+: base prompt + correction prefix listing exactly which rules failed.
  // Loop exits on: pass, repair, fail, or non-retryable HTTP error.

  let lastFailureSummary = "";
  let retryPrefix = "";

  for (let attempt = 1; attempt <= VALIDATION.MAX_ATTEMPTS; attempt++) {
    const isRetry = attempt > 1;

    if (isRetry) {
      console.warn(`[analyze] Retry ${attempt}/${VALIDATION.MAX_ATTEMPTS}: ${lastFailureSummary}`);
    }

    // ── HTTP call ──────────────────────────────────────────────────────────
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

    let response: Response;
    try {
      response = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${openAIApiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: ANALYSIS_MODEL,
          messages: [
            { role: "system", content: systemPrompt },
            {
              role: "user",
              // On retries: prepend the correction prefix so model knows exactly what to fix.
              // Temperature is raised slightly on retries to avoid the model repeating itself.
              content: isRetry ? `${retryPrefix}

---

${userPrompt}` : userPrompt,
            },
          ],
          tools: [toolSchema],
          tool_choice: { type: "function", function: { name: "submit_analysis" } },
          // Slight temperature increase on retries to break out of a bad mode
          temperature: isRetry ? 0.35 : 0.2,
        }),
        signal: controller.signal,
      });
    } finally {
      clearTimeout(timeoutId);
    }

    // ── HTTP error handling ────────────────────────────────────────────────
    if (!response.ok) {
      const errText = await response.text();
      if (response.status === 429) {
        // Retry with exponential backoff instead of failing immediately
        const backoffMs = Math.min(2000 * Math.pow(2, attempt - 1), 16000);
        console.warn(`[analyze] OpenAI rate limit (attempt ${attempt}), retrying in ${backoffMs}ms`);
        await new Promise((r) => setTimeout(r, backoffMs));
        continue;
      }
      if (response.status === 402) throw Object.assign(new Error("credits_exhausted"), { status: 402 });
      console.error(`[analyze] AI gateway error (attempt ${attempt}):`, response.status, errText);
      // Gateway errors are not retried — they are infrastructure failures
      throw Object.assign(new Error("ai_gateway_error"), { status: 502 });
    }

    // ── Parse response ─────────────────────────────────────────────────────
    const data = await response.json();
    const message = data?.choices?.[0]?.message;
    const toolCall = message?.tool_calls?.[0];

    let parsedRaw: any = null;

    if (toolCall?.function?.arguments) {
      try {
        parsedRaw = JSON.parse(toolCall.function.arguments);
      } catch (e) {
        console.error(`[analyze] JSON parse error (attempt ${attempt}):`, e);
        // parsedRaw stays null — validator will treat this as malformed
      }
    }

    if (!parsedRaw) {
      const contentText = getMessageContentAsText(message?.content);
      if (contentText) parsedRaw = tryExtractJsonFromText(contentText);
    }

    // ── Validate ───────────────────────────────────────────────────────────
    const decision = validateAiOutput(parsedRaw, attempt);
    console.info(`[analyze] Attempt ${attempt} → ${decision.summary}`);

    if (decision.action === "pass") {
      // ✅ Output meets all quality rules — merge and return
      const analysis = mergeAnalysisLayers(deterministicScores, parsedRaw, language);
      return { analysis, normalizedInput, deterministicScores };
    }

    if (decision.action === "repair") {
      // 🔧 Minor out-of-range values fixed in place — merge repaired object
      console.warn(`[analyze] Repaired output on attempt ${attempt}`);
      const analysis = mergeAnalysisLayers(deterministicScores, decision.repaired!, language);
      return { analysis, normalizedInput, deterministicScores };
    }

    if (decision.action === "fail") {
      // ❌ Max attempts exhausted with persistent failures
      console.error(`[analyze] Output failed validation after ${attempt} attempts.`, decision.failures);
      // Last-resort: if we have ANY parsedRaw, use it (better than nothing)
      // but log that it is sub-quality.
      if (parsedRaw) {
        console.warn(`[analyze] Using sub-quality output as last resort.`);
        const analysis = mergeAnalysisLayers(deterministicScores, parsedRaw, language);
        return { analysis, normalizedInput, deterministicScores };
      }
      throw Object.assign(
        new Error(`AI output failed ${decision.failures.length} quality rules after ${VALIDATION.MAX_ATTEMPTS} attempts`),
        { status: 502, validation_failures: decision.failures }
      );
    }

    // decision.action === "retry" — prepare correction prefix for next loop
    lastFailureSummary = decision.summary;
    retryPrefix = buildRetryPrefix(decision.failures, attempt);
    // Continue to next iteration
  }

  // Should never reach here (loop covers 1..MAX_ATTEMPTS and always returns/throws)
  throw Object.assign(new Error("analysis_retry_exhausted"), { status: 502 });
}

/**
 * TALENTRY — Deterministic Resume Normalizer (Deno-compatible)
 * Pure TypeScript. Zero AI. Shared by job seeker + recruiter analysis flows.
 */

export interface NormalizedResumeInput {
  name: string | null;
  job_title: string | null;
  summary: string | null;
  skills: string[];
  experience: string[];
  education: string[] | null;
  certifications: string[] | null;
  raw_text: string;
}

type SectionKey = "summary" | "experience" | "skills" | "education" | "certifications";

const SECTION_PATTERNS: Array<{ key: SectionKey; patterns: RegExp[] }> = [
  {
    key: "summary",
    patterns: [/^professional\s+summary$/i, /^summary$/i, /^profile$/i, /^career\s+summary$/i, /^objective$/i, /^about\s+me$/i, /^الملخص$/i, /^الملخص\s+المهني$/i, /^الهدف\s+الوظيفي$/i, /^نبذة$/i, /^نبذه$/i, /^نبذة\s+مهنية$/i],
  },
  {
    key: "experience",
    patterns: [/^experience$/i, /^work\s+experience$/i, /^employment$/i, /^employment\s+history$/i, /^professional\s+experience$/i, /^work\s+history$/i, /^career\s+history$/i, /^الخبرة$/i, /^الخبرات$/i, /^الخبرة\s+المهنية$/i, /^الخبرات\s+العملية$/i, /^السجل\s+الوظيفي$/i],
  },
  {
    key: "skills",
    patterns: [/^skills$/i, /^technical\s+skills$/i, /^core\s+skills$/i, /^key\s+skills$/i, /^core\s+competencies$/i, /^competencies$/i, /^المهارات$/i, /^مهارات$/i, /^المهارات\s+التقنية$/i, /^الكفاءات$/i, /^المهارات\s+الأساسية$/i],
  },
  {
    key: "education",
    patterns: [/^education$/i, /^academic$/i, /^academic\s+background$/i, /^qualifications?$/i, /^التعليم$/i, /^المؤهلات$/i, /^المؤهلات\s+العلمية$/i, /^الخلفية\s+الأكاديمية$/i],
  },
  {
    key: "certifications",
    patterns: [/^certifications?$/i, /^certificates?$/i, /^licenses?$/i, /^courses?$/i, /^training$/i, /^الشهادات$/i, /^الشهادات\s+المهنية$/i, /^الدورات$/i, /^الدورات\s+التدريبية$/i, /^الرخص$/i, /^الاعتمادات$/i],
  },
];

const NOISE_PATTERNS: RegExp[] = [
  /^page\s+\d+(\s+of\s+\d+)?$/i,
  /^صفحة\s+\d+$/i,
  /^curriculum\s+vitae$/i,
  /^resume$/i,
  /^\s*cv\s*$/i,
  /^\d+\s*\/\s*\d+$/,
  /^[-_=*•▪◦]{3,}$/,
];

const JOB_TITLE_HINTS = /engineer|manager|specialist|supervisor|analyst|developer|consultant|officer|lead|director|coordinator|assistant|administrator|architect|designer|executive|technician|support|hr|accountant|marketing|sales|network|security|project|مهندس|مدير|أخصائي|مشرف|محلل|مطور|استشاري|مسؤول|منسق|فني|محاسب|موارد بشرية|دعم فني|شبكات|أمن|مبيعات|تسويق/i;
const SKILL_BANK = [
  "sql","oracle","excel","power bi","powerbi","python","java","javascript","typescript","react","node","aws","azure","docker","kubernetes","git","linux","windows server","ccna","fortinet","bgp","ospf","mpls","vrf","ipvpn","dia","jira","sap","erp","crm","salesforce","hubspot","seo","sem","google analytics","autocad","revit","pmp","itil","troubleshooting","technical support","customer service","networking","saudization","gosi","nitaqat","recruitment","onboarding","payroll","hrsd","data analysis","sql server","oracle db","windows","microsoft office"
];
const EXPERIENCE_HINT = /(19|20)\d{2}|present|current|now|till now|to date|حتى الآن|حالياً|الآن|شركة|company|ltd|llc|inc|corp|group|مؤسسة|مجموعة/i;
const EDUCATION_HINT = /bachelor|master|diploma|phd|doctorate|university|college|degree|graduated|education|بكالوريوس|ماجستير|دبلوم|دكتوراه|جامعة|كلية|مؤهل|تعليم/i;
const CERT_HINT = /certif|certificate|license|course|training|ccna|pmp|itil|aws|azure|nse|jncia|jncis|osha|شهادة|دورة|اعتماد|رخصة/i;

function stripInvisible(text: string): string {
  return text
    .replace(/\x00/g, "")
    .replace(/[\u200B\u200C\u200D\uFEFF]/g, "")
    .replace(/\u00A0/g, " ")
    .replace(/\t/g, " ");
}

function collapseSpaces(line: string): string {
  return line.replace(/[ ]+/g, " ").trim();
}

function normalizeHeadingText(line: string): string {
  return line.replace(/^#+\s*/, "").replace(/[|]+/g, " ").replace(/[:：\-–—]+$/, "").replace(/\s+/g, " ").trim();
}

function detectSection(line: string): SectionKey | null {
  const normalized = normalizeHeadingText(line);
  if (!normalized || normalized.length > 70) return null;
  for (const item of SECTION_PATTERNS) {
    if (item.patterns.some((rx) => rx.test(normalized))) return item.key;
  }
  return null;
}

function isBulletLine(line: string): boolean {
  return /^[•▪◦*\-–—]\s+/.test(line.trim());
}

function looksLikeContact(line: string): boolean {
  return /@/.test(line) || /\+?\d[\d\s()\-]{6,}/.test(line) || /linkedin|github|portfolio|email|mobile|phone|tel|address|location|البريد|الهاتف|الجوال|العنوان/i.test(line);
}

function looksLikeName(line: string): boolean {
  if (!line || line.length > 60 || looksLikeContact(line) || detectSection(line)) return false;
  if (/\d/.test(line)) return false;
  const words = line.split(/\s+/).filter(Boolean);
  return words.length >= 2 && words.length <= 6 && /^[A-Za-z\u0600-\u06FF\s.'\-]+$/.test(line);
}

function looksLikeJobTitle(line: string): boolean {
  return !!line && line.length <= 90 && !looksLikeContact(line) && !detectSection(line) && JOB_TITLE_HINTS.test(line);
}

function normalizeLine(line: string): string {
  return collapseSpaces(stripInvisible(line))
    .replace(/^\s*[•▪◦]+\s*/g, "• ")
    .replace(/^\s*[-–—*]+\s*/g, "- ")
    .replace(/\s+([,.;:])/g, "$1")
    .trim();
}

function mergeWrappedLines(lines: string[]): string[] {
  const out: string[] = [];
  for (const line of lines) {
    if (!out.length) {
      out.push(line);
      continue;
    }
    const prev = out[out.length - 1];
    const startsNewItem = isBulletLine(line) || looksLikeContact(line) || !!detectSection(line) || looksLikeName(line) || looksLikeJobTitle(line);
    const prevIsSoft = /[,;:\-–—]$/.test(prev) || (prev.length < 55 && !isBulletLine(prev));
    if (prevIsSoft && !startsNewItem) {
      out[out.length - 1] = `${prev} ${line}`.replace(/\s+/g, " ").trim();
    } else {
      out.push(line);
    }
  }
  return out;
}

function cleanResumeText(rawText: string): string {
  return stripInvisible(rawText)
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[ ]{2,}/g, " ")
    .replace(/\n{3,}/g, "\n\n");
}

function shouldDropLine(line: string): boolean {
  if (!line) return true;
  if (NOISE_PATTERNS.some((rx) => rx.test(line))) return true;
  if (/^[^\w\u0600-\u06FF]+$/.test(line) && line.length < 4) return true;
  return false;
}

function uniqueStrings(values: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const value of values) {
    const clean = value.trim().replace(/^[•▪◦*\-–—]\s*/, "").trim();
    if (!clean) continue;
    const key = clean.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(clean);
  }
  return out;
}

function splitListLikeText(text: string): string[] {
  return uniqueStrings(
    text
      .split(/\n|\||•|▪|◦|;|،|,/)
      .map((part) => part.trim())
      .filter((part) => part.length >= 2),
  );
}

function extractKeywords(rawText: string): string[] {
  const lowered = rawText.toLowerCase();
  const found = SKILL_BANK.filter((skill) => lowered.includes(skill.toLowerCase()));
  const listCandidates = rawText
    .split("\n")
    .filter((line) => line.includes(",") || isBulletLine(line))
    .flatMap((line) => splitListLikeText(line))
    .filter((item) => item.length >= 2 && item.length <= 40 && !EXPERIENCE_HINT.test(item) && !EDUCATION_HINT.test(item));

  return uniqueStrings([...found, ...listCandidates]).slice(0, 20);
}

function extractExperienceBlocks(rawText: string): string[] {
  const lines = rawText.split("\n").map((l) => l.trim()).filter(Boolean);
  const blocks: string[] = [];
  let buffer: string[] = [];

  const flush = () => {
    if (!buffer.length) return;
    const joined = buffer.join(" ").replace(/\s+/g, " ").trim();
    if (joined.length >= 20) blocks.push(joined);
    buffer = [];
  };

  for (const line of lines) {
    const jobish = JOB_TITLE_HINTS.test(line) || EXPERIENCE_HINT.test(line);
    if (jobish && buffer.length >= 2) flush();
    if (jobish || buffer.length) {
      buffer.push(line.replace(/^[•▪◦*\-–—]\s*/, "").trim());
      if (buffer.length >= 4) flush();
    }
  }
  flush();

  const fallbackJoined = lines
    .filter((line) => JOB_TITLE_HINTS.test(line) || EXPERIENCE_HINT.test(line))
    .slice(0, 6);

  return uniqueStrings(blocks.length ? blocks : fallbackJoined).slice(0, 8);
}

function extractNameAndTitle(lines: string[]): { name: string | null; job_title: string | null } {
  let name: string | null = null;
  let job_title: string | null = null;
  for (const line of lines.slice(0, 12)) {
    if (!name && looksLikeName(line)) {
      name = line;
      continue;
    }
    if (!job_title && looksLikeJobTitle(line)) {
      job_title = line;
    }
  }
  return { name, job_title };
}

function arrayToParagraph(lines: string[]): string | null {
  const text = uniqueStrings(lines).join(" ").replace(/\s+/g, " ").trim();
  return text || null;
}

function normalizeSectionArray(lines: string[]): string[] {
  return uniqueStrings(lines)
    .map((line) => line.replace(/^[•▪◦*\-–—]\s*/, "").trim())
    .filter(Boolean);
}

export function normalizeResumeText(rawText: string): NormalizedResumeInput {
  if (!rawText || !rawText.trim()) {
    return {
      name: null,
      job_title: null,
      summary: null,
      skills: [],
      experience: [],
      education: null,
      certifications: null,
      raw_text: "",
    };
  }

  const cleaned = cleanResumeText(rawText);
  const rawLines = cleaned
    .split("\n")
    .map(normalizeLine)
    .filter((line) => !shouldDropLine(line));
  const lines = mergeWrappedLines(rawLines);
  const raw_text = lines.join("\n").replace(/\n{3,}/g, "\n\n").trim();

  const buckets: Record<SectionKey, string[]> = {
    summary: [],
    experience: [],
    skills: [],
    education: [],
    certifications: [],
  };

  const { name, job_title } = extractNameAndTitle(lines);
  let currentSection: SectionKey | null = null;

  for (const line of lines) {
    const sectionKey = detectSection(line);
    if (sectionKey) {
      currentSection = sectionKey;
      continue;
    }
    if (looksLikeContact(line)) continue;
    if (line === name || line === job_title) continue;

    if (currentSection) {
      buckets[currentSection].push(line);
      continue;
    }

    if (CERT_HINT.test(line)) {
      buckets.certifications.push(line);
    } else if (EDUCATION_HINT.test(line)) {
      buckets.education.push(line);
    } else if (JOB_TITLE_HINTS.test(line) || EXPERIENCE_HINT.test(line)) {
      buckets.experience.push(line);
    } else if (line.includes(",") || isBulletLine(line) || SKILL_BANK.some((skill) => line.toLowerCase().includes(skill))) {
      buckets.skills.push(line);
    } else if (buckets.summary.join(" ").length < 1200) {
      buckets.summary.push(line);
    }
  }

  let skills = normalizeSectionArray(buckets.skills.flatMap((line) => splitListLikeText(line)));
  let experience = normalizeSectionArray(buckets.experience);
  let education = normalizeSectionArray(buckets.education);
  let certifications = normalizeSectionArray(buckets.certifications);
  const summary = arrayToParagraph(buckets.summary);

  if (skills.length === 0 || experience.length === 0) {
    const fallbackSkills = extractKeywords(raw_text);
    const fallbackExperience = extractExperienceBlocks(raw_text);
    if (skills.length === 0) skills = fallbackSkills;
    if (experience.length === 0) experience = fallbackExperience;
  }

  if (skills.length < 3 && raw_text.length > 120) {
    skills = uniqueStrings([...skills, ...extractKeywords(raw_text)]).slice(0, 20);
  }

  if (experience.length === 0 && raw_text.length > 120) {
    experience = extractExperienceBlocks(raw_text);
  }

  if (education.length === 0) education = uniqueStrings(lines.filter((line) => EDUCATION_HINT.test(line))).slice(0, 6);
  if (certifications.length === 0) certifications = uniqueStrings(lines.filter((line) => CERT_HINT.test(line))).slice(0, 8);

  return {
    name: name ?? null,
    job_title: job_title ?? null,
    summary,
    skills,
    experience,
    education: education.length ? education : null,
    certifications: certifications.length ? certifications : null,
    raw_text,
  };
}

function sectionToText(value: string[] | string | null | undefined): string {
  if (!value) return "";
  if (Array.isArray(value)) return value.join("\n").trim();
  return value.trim();
}

export function prepareTextForPrompt(normalized: NormalizedResumeInput): string {
  const parts: string[] = [];
  const weakStructure = normalized.skills.length < 3 || normalized.experience.length < 1;

  if (normalized.name) parts.push(`NAME: ${normalized.name}`);
  if (normalized.job_title) parts.push(`CURRENT/TARGET TITLE: ${normalized.job_title}`);
  if (weakStructure) parts.push(`NOTE: The resume is unstructured. Extract missing sections before analysis.`);
  if (normalized.summary) parts.push(`\n── SUMMARY ──\n${normalized.summary}`);
  if (normalized.experience.length) parts.push(`\n── EXPERIENCE ──\n${sectionToText(normalized.experience)}`);
  if (normalized.skills.length) parts.push(`\n── SKILLS ──\n${sectionToText(normalized.skills)}`);
  if (normalized.education?.length) parts.push(`\n── EDUCATION ──\n${sectionToText(normalized.education)}`);
  if (normalized.certifications?.length) parts.push(`\n── CERTIFICATIONS ──\n${sectionToText(normalized.certifications)}`);
  // Always include raw text so AI can catch anything the normalizer missed.
  // Truncate raw_text to 30K chars to stay well within prompt token limits
  // while preserving full content for typical resumes (1-3 pages ≈ 3-20K chars).
  const rawSnippet = normalized.raw_text.length > 30_000
    ? normalized.raw_text.substring(0, 30_000) + "\n[... truncated for length ...]"
    : normalized.raw_text;
  parts.push(`\n── CLEANED RAW TEXT ──\n${rawSnippet}`);
  return parts.join("\n").trim();
}

/**
 * TALENTRY — AI Output Validator
 * ─────────────────────────────────────────────────────────────────────────────
 * Validates raw AI JSON responses BEFORE they reach mergeAnalysisLayers(),
 * the UI, or the database.
 *
 * DESIGN GOALS
 *   • Catch shallow / generic / malformed AI output early
 *   • Return a typed decision: pass | retry | repair
 *   • Never allow an infinite retry loop
 *   • Keep every rule explicit — no magic thresholds buried in conditions
 *
 * USAGE (called inside callAnalysisAI):
 *   const decision = validateAiOutput(parsedRaw, attempt);
 *   if (decision.action === "pass")   → proceed to mergeAnalysisLayers()
 *   if (decision.action === "retry")  → re-call OpenAI with stricter prompt
 *   if (decision.action === "repair") → use decision.repaired object
 *   if (decision.action === "fail")   → max retries exceeded; throw structured error
 */

// ═══════════════════════════════════════════════════════════════════════════════
// CONSTANTS  — every threshold is named; change here only
// ═══════════════════════════════════════════════════════════════════════════════

export const VALIDATION = {
  /** Maximum AI attempts (attempt 1 = initial call, attempts 2..N = retries) */
  MAX_ATTEMPTS: 6,

  // ── Structural minimums ────────────────────────────────────────────────────
  MIN_STRENGTHS:           3,   // executive_summary.top_strengths
  MIN_RISKS:               3,   // executive_summary.main_risks
  MIN_IMPROVEMENTS:        5,   // quick_improvements total items
  MIN_HIGH_IMPROVEMENTS:   2,   // quick_improvements where priority === "high"
  MIN_INTERVIEW_QUESTIONS: 5,   // interview_questions
  MIN_SALARY_ROWS:         1,   // salary_estimation.salary_table
  MIN_REWRITE_WORDS:      50,   // resume_rewrite.full_resume word count

  // ── Keyword gap requirement ────────────────────────────────────────────────
  /** ats_breakdown_narratives.keywords.problem must name at least this many
   *  distinct words that look like actual skill/tool names (not generic text) */
  MIN_KEYWORD_GAPS_NAMED:  2,

  // ── Generic-content detection ──────────────────────────────────────────────
  /** Phrases that indicate the AI produced a template response, not a
   *  resume-specific one.  Any match → RETRY. */
  BANNED_GENERIC_PHRASES: [
    "strong communication skills",
    "team player",
    "fast learner",
    "results-driven",
    "detail-oriented",
    "passionate about",
    "seeking opportunities",
    "please confirm",         // only banned if it appears in strengths/risks
    "highly motivated",
    "dynamic professional",
    "[please confirm]",
    "[يرجى التأكيد]",          // fallback placeholder in strengths = hallucination
  ] as readonly string[],

  /** Minimum character length for a useful summary_paragraphs */
  MIN_SUMMARY_CHARS: 80,

  // ── Score repair rules ─────────────────────────────────────────────────────
  /** If AI somehow returns a score outside this range, we repair it to the
   *  deterministic engine value rather than retrying the whole call. */
  VALID_SCORE_MIN: 0,
  VALID_SCORE_MAX: 100,
} as const;

// ═══════════════════════════════════════════════════════════════════════════════
// TYPES
// ═══════════════════════════════════════════════════════════════════════════════

export type ValidationAction = "pass" | "retry" | "repair" | "fail";

export interface ValidationFailure {
  rule: string;
  detail: string;
}

export interface ValidationDecision {
  action: ValidationAction;
  failures: ValidationFailure[];
  /** Only set when action === "repair" */
  repaired?: Record<string, unknown>;
  /** Human-readable summary for logging */
  summary: string;
}

// ═══════════════════════════════════════════════════════════════════════════════
// PRIVATE HELPERS
// ═══════════════════════════════════════════════════════════════════════════════

function asArray(v: unknown): unknown[] {
  return Array.isArray(v) ? v : [];
}

function asString(v: unknown): string {
  return typeof v === "string" ? v.trim() : "";
}

function wordCount(text: string): number {
  return text.split(/\s+/).filter(Boolean).length;
}

function containsGenericPhrase(text: string): string | null {
  const lower = text.toLowerCase();
  for (const phrase of VALIDATION.BANNED_GENERIC_PHRASES) {
    if (lower.includes(phrase.toLowerCase())) return phrase;
  }
  return null;
}

/** Check whether a string names at least N real keyword tokens
 *  (heuristic: word/phrase that is ≥ 3 chars and not purely stopwords) */
function countNamedKeywords(text: string): number {
  if (!text) return 0;
  // Split on commas, semicolons, bullets, newlines
  const tokens = text
    .split(/[,;\n•▪\-–]/)
    .map((t) => t.trim())
    .filter((t) => t.length >= 3 && !/^(and|or|the|for|not|any|all|with|from|that|this|missing|absent|lacks?|no |found)$/i.test(t));
  return tokens.length;
}

function isScoreValid(v: unknown): boolean {
  const n = Number(v);
  return Number.isFinite(n) && n >= VALIDATION.VALID_SCORE_MIN && n <= VALIDATION.VALID_SCORE_MAX;
}

// ═══════════════════════════════════════════════════════════════════════════════
// MAIN VALIDATOR
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Validate a raw AI tool-call output object.
 *
 * @param raw      Parsed JSON from the AI tool call (before mergeAnalysisLayers)
 * @param attempt  Current attempt number (1 = first call, 2/3 = retries)
 * @returns        ValidationDecision — caller acts on .action
 */
export function validateAiOutput(raw: unknown, attempt: number): ValidationDecision {
  const failures: ValidationFailure[] = [];

  // ── 0. Structural guard — must be a non-null object ─────────────────────────
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return {
      action: attempt >= VALIDATION.MAX_ATTEMPTS ? "fail" : "retry",
      failures: [{ rule: "malformed_json", detail: "AI output is not a valid JSON object" }],
      summary: "FAIL: AI returned non-object payload",
    };
  }

  const r = raw as Record<string, unknown>;

  // Convenience accessors for nested paths
  const execSummary   = (r.executive_summary  ?? {}) as Record<string, unknown>;
  const narratives    = (r.ats_breakdown_narratives ?? r.ats_breakdown ?? {}) as Record<string, unknown>;
  const keywordsBlock = (narratives.keywords ?? {}) as Record<string, unknown>;
  const improvements  = asArray(r.quick_improvements);
  const strengths     = asArray(execSummary.top_strengths);
  const risks         = asArray(execSummary.main_risks);
  const questions     = asArray(r.interview_questions);
  const salaryTable   = asArray((r.salary_estimation as any)?.salary_table);
  const rewriteText   = asString((r.resume_rewrite as any)?.full_resume);
  const summaryText   = asString(execSummary.summary_paragraphs);

  // ── Rule 1: top_strengths — must have ≥ 3 items ────────────────────────────
  if (strengths.length < VALIDATION.MIN_STRENGTHS) {
    failures.push({
      rule: "insufficient_strengths",
      detail: `Got ${strengths.length} strengths, need ≥ ${VALIDATION.MIN_STRENGTHS}`,
    });
  }

  // ── Rule 2: main_risks — must have ≥ 3 items ───────────────────────────────
  if (risks.length < VALIDATION.MIN_RISKS) {
    failures.push({
      rule: "insufficient_risks",
      detail: `Got ${risks.length} risks, need ≥ ${VALIDATION.MIN_RISKS}`,
    });
  }

  // ── Rule 3: quick_improvements — total ≥ 5 AND ≥ 2 marked "high" ──────────
  if (improvements.length < VALIDATION.MIN_IMPROVEMENTS) {
    failures.push({
      rule: "insufficient_improvements",
      detail: `Got ${improvements.length} improvements, need ≥ ${VALIDATION.MIN_IMPROVEMENTS}`,
    });
  } else {
    const highCount = improvements.filter(
      (item) => (item as any)?.priority === "high"
    ).length;
    if (highCount < VALIDATION.MIN_HIGH_IMPROVEMENTS) {
      failures.push({
        rule: "insufficient_high_priority_improvements",
        detail: `Got ${highCount} high-priority improvements, need ≥ ${VALIDATION.MIN_HIGH_IMPROVEMENTS}`,
      });
    }
  }

  // ── Rule 4: keyword gap — keywords.problem must name real keywords ──────────
  const keywordProblem = asString(keywordsBlock.problem);
  const namedGaps      = countNamedKeywords(keywordProblem);
  if (namedGaps < VALIDATION.MIN_KEYWORD_GAPS_NAMED) {
    failures.push({
      rule: "missing_keywords_not_named",
      detail: `ats_breakdown.keywords.problem has ${namedGaps} named keywords, need ≥ ${VALIDATION.MIN_KEYWORD_GAPS_NAMED}. Got: "${keywordProblem.slice(0, 80)}"`,
    });
  }

  // ── Rule 5: summary_paragraphs — must have meaningful content ──────────────
  if (summaryText.length < VALIDATION.MIN_SUMMARY_CHARS) {
    failures.push({
      rule: "summary_too_short",
      detail: `summary_paragraphs has ${summaryText.length} chars, need ≥ ${VALIDATION.MIN_SUMMARY_CHARS}`,
    });
  }

  // ── Rule 6: generic/template phrases in strengths or risks ─────────────────
  for (const item of [...strengths, ...risks]) {
    const text = asString(item);
    const match = containsGenericPhrase(text);
    if (match) {
      failures.push({
        rule: "generic_content",
        detail: `Banned generic phrase "${match}" found in strengths/risks: "${text.slice(0, 80)}"`,
      });
      break; // one failure per call is enough to trigger retry
    }
  }

  // ── Rule 7: interview questions — ≥ 5 ──────────────────────────────────────
  if (questions.length < VALIDATION.MIN_INTERVIEW_QUESTIONS) {
    failures.push({
      rule: "insufficient_interview_questions",
      detail: `Got ${questions.length} interview questions, need ≥ ${VALIDATION.MIN_INTERVIEW_QUESTIONS}`,
    });
  }

  // ── Rule 8: salary table — at least 1 row with real SAR numbers ────────────
  const hasValidSalaryRow = salaryTable.some((row) => {
    const low  = Number((row as any)?.monthly_range_low);
    const high = Number((row as any)?.monthly_range_high);
    return Number.isFinite(low) && Number.isFinite(high) && low > 0 && high > low;
  });
  if (salaryTable.length < VALIDATION.MIN_SALARY_ROWS || !hasValidSalaryRow) {
    failures.push({
      rule: "invalid_salary_table",
      detail: `salary_table has ${salaryTable.length} rows; valid SAR row found: ${hasValidSalaryRow}`,
    });
  }

  // ── Rule 9: resume rewrite — must be a real document, not a placeholder ────
  if (wordCount(rewriteText) < VALIDATION.MIN_REWRITE_WORDS) {
    failures.push({
      rule: "resume_rewrite_too_short",
      detail: `resume_rewrite.full_resume has ${wordCount(rewriteText)} words, need ≥ ${VALIDATION.MIN_REWRITE_WORDS}`,
    });
  }

  // ── Rule 10: score repair (non-retryable — just fix in place) ──────────────
  // If AI returned any score fields despite being told not to, and they are
  // out of range, we mark for repair rather than a retry.
  const repairNeeded: Record<string, unknown> = {};
  let needsRepair = false;

  for (const key of ["ats_score"] as const) {
    if (key in r && !isScoreValid(r[key])) {
      repairNeeded[key] = 0; // will be overridden by deterministicScores anyway
      needsRepair = true;
      // This is a repair, not a retry — don't add to failures
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // DECISION
  // ═══════════════════════════════════════════════════════════════════════════

  // If output has no structural failures, it passes (even if repair was needed)
  if (failures.length === 0) {
    if (needsRepair) {
      return {
        action: "repair",
        failures: [],
        repaired: { ...r, ...repairNeeded },
        summary: `REPAIR: Score fields out of range — repaired in place`,
      };
    }
    return {
      action: "pass",
      failures: [],
      summary: "PASS: All validation rules satisfied",
    };
  }

  // Failures exist — decide retry vs fail based on attempt count
  const failureNames = failures.map((f) => f.rule).join(", ");

  if (attempt >= VALIDATION.MAX_ATTEMPTS) {
    return {
      action: "fail",
      failures,
      summary: `FAIL after ${attempt} attempts. Unresolved rules: ${failureNames}`,
    };
  }

  return {
    action: "retry",
    failures,
    summary: `RETRY (attempt ${attempt}/${VALIDATION.MAX_ATTEMPTS}). Failed rules: ${failureNames}`,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// RETRY PROMPT INJECTION
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Build a correction prefix injected at the TOP of the user prompt on retries.
 * Explicitly tells the model what it got wrong in the previous attempt,
 * without leaking the bad output back to it.
 */
export function buildRetryPrefix(failures: ValidationFailure[], attempt: number): string {
  const lines: string[] = [
    `⚠ CORRECTION REQUIRED (attempt ${attempt} of ${VALIDATION.MAX_ATTEMPTS})`,
    `Your previous response failed ${failures.length} quality rule(s). Fix ALL of the following:`,
    "",
  ];

  const RULE_INSTRUCTIONS: Record<string, string> = {
    insufficient_strengths:
      `• top_strengths: provide EXACTLY 3 items. Each must cite specific resume evidence in the format: "[Strength]: [Evidence] → [GCC relevance]"`,
    insufficient_risks:
      `• main_risks: provide EXACTLY 3 items. Each must name a specific, honest hiring risk: "[Risk]: [Evidence] → [Recruiter impact]"`,
    insufficient_improvements:
      `• quick_improvements: provide EXACTLY 12 items total (≥5 high, ≥4 medium, ≥3 low). Each must name a specific section and exact change.`,
    insufficient_high_priority_improvements:
      `• quick_improvements: at least ${VALIDATION.MIN_HIGH_IMPROVEMENTS} items must have priority "high". Review your list.`,
    missing_keywords_not_named:
      `• ats_breakdown_narratives.keywords.problem: LIST at least ${VALIDATION.MIN_KEYWORD_GAPS_NAMED} specific missing keywords by name (e.g. "Power BI, Nitaqat, PMP"). Do not write generic sentences.`,
    summary_too_short:
      `• executive_summary.summary_paragraphs: write at least 3 full paragraphs (≥80 chars total). Cover: overall impression, value proposition, and critical gaps.`,
    generic_content:
      `• Remove ALL generic phrases from strengths and risks. Banned: "strong communication skills", "team player", "results-driven", "passionate about", etc. Every item must reference specific resume content.`,
    insufficient_interview_questions:
      `• interview_questions: provide at least ${VALIDATION.MIN_INTERVIEW_QUESTIONS} questions. Each must have a detailed suggested_answer_direction.`,
    invalid_salary_table:
      `• salary_estimation.salary_table: provide at least 1 row with valid SAR monthly figures (monthly_range_low > 0 and monthly_range_high > monthly_range_low).`,
    resume_rewrite_too_short:
      `• resume_rewrite.full_resume: write a complete resume document (at least ${VALIDATION.MIN_REWRITE_WORDS} words). It must include: Header, Summary, Skills, Experience (with bullets), Education.`,
  };

  for (const failure of failures) {
    const instruction = RULE_INSTRUCTIONS[failure.rule];
    if (instruction) {
      lines.push(instruction);
    } else {
      lines.push(`• [${failure.rule}]: ${failure.detail}`);
    }
  }

  lines.push("", "Produce a complete, corrected response now. Do not acknowledge this message — just output the fixed tool call.");
  return lines.join("\n");
}

/**
 * TALENTRY — Deterministic ATS Scoring Engine (Layer A)
 * ══════════════════════════════════════════════════════
 * Pure rule-based scoring. Zero AI. Zero randomness.
 * Same resume text in → identical scores out, every single time.
 *
 * ── OFFICIAL SCORING FORMULA ──────────────────────────────────────────────────
 *
 *   Factor                    Weight   Scorer function
 *   ─────────────────────────────────────────────────
 *   Section completeness       20%     scoreSectionCompleteness()
 *   Skills presence/relevance  20%     scoreSkillsPresence()
 *   Experience clarity         15%     scoreExperienceClarity()
 *   Measurable achievements    15%     scoreMeasurableAchievements()
 *   Keyword coverage           15%     scoreKeywordCoverage()
 *   Formatting & readability   10%     scoreFormatting()
 *   Summary quality             5%     scoreSummaryQuality()
 *   ─────────────────────────────────────────────────
 *   TOTAL                     100%
 *
 * ── RULES ─────────────────────────────────────────────────────────────────────
 *   • overall_score ∈ [0, 100], integer, clamped after weighted sum
 *   • Every factor score ∈ [0, 100], integer, clamped independently
 *   • Every deduction and bonus is a named constant — no magic numbers in logic
 *   • No AI call, no external I/O, no Date.random(), no floating-point surprise
 *   • The AI layer (Layer B) in analysis-core.ts may NOT override any numeric value
 *
 * ── ARCHITECTURE ──────────────────────────────────────────────────────────────
 *   Callers use only:
 *     computeAtsScores(normalized, rawText) → DeterministicScores
 *   Everything else in this file is private implementation.
 */

import type { NormalizedResumeInput } from "./resume-normalizer.ts";

// ═══════════════════════════════════════════════════════════════════════════════
// PUBLIC TYPES
// ═══════════════════════════════════════════════════════════════════════════════

export interface FactorScore {
  /** 0–100 integer */
  score: number;
  /** What the engine observed in the resume */
  current_state: string;
  /** Specific problem found, or empty string if none */
  problem: string;
  /** Exact, actionable fix instruction */
  recommended_improvement: string;
}

export interface DeterministicScores {
  /** Authoritative composite ATS score 0–100. AI must not override. */
  overall_score: number;

  /** Individual factor scores — all 0–100, all deterministic */
  factor_scores: {
    section_completeness: number;    // weight 20%
    skills_presence: number;         // weight 20%
    experience_clarity: number;      // weight 15%
    measurable_achievements: number; // weight 15%
    keyword_coverage: number;        // weight 15%
    formatting: number;              // weight 10%
    summary_quality: number;         // weight  5%
  };

  /** Per-factor detail with narratives — used by AI Layer B for commentary */
  factor_breakdown: {
    section_completeness: FactorScore;
    skills_presence: FactorScore;
    experience_clarity: FactorScore;
    measurable_achievements: FactorScore;
    keyword_coverage: FactorScore;
    formatting: FactorScore;
    summary_quality: FactorScore;
  };

  // ── Legacy aliases ────────────────────────────────────────────────────────
  // Kept so analysis-core.ts mergeAnalysisLayers() and the AI prompt context
  // can reference these without a breaking change.
  /** @alias overall_score */
  ats_score: number;
  /** Maps factors to the NormalizedAnalysis.section_scores schema */
  section_scores: {
    resume_formatting: number;
    keyword_optimization: number;
    experience_quality: number;
    career_progression: number;
    skills_relevance: number;
    education_strength: number;
    contact_information_quality: number;
  };
  /** Legacy ats_breakdown shape expected by mergeAnalysisLayers() */
  ats_breakdown: {
    formatting: FactorScore;
    sections: FactorScore;
    keywords: FactorScore;
    experience: FactorScore;
    education: FactorScore;
    skills: FactorScore;
    contact_info: FactorScore;
  };

  // ── Metadata ──────────────────────────────────────────────────────────────
  candidate_level: "junior" | "mid" | "senior" | "executive";
  years_of_experience: number;
  missing_sections: string[];
  keywords_found: string[];
  keywords_missing_hints: string[];
}

// ═══════════════════════════════════════════════════════════════════════════════
// SCORING WEIGHTS  — edit here and nowhere else
// ═══════════════════════════════════════════════════════════════════════════════

const W = {
  section_completeness:    0.20,
  skills_presence:         0.20,
  experience_clarity:      0.15,
  measurable_achievements: 0.15,
  keyword_coverage:        0.15,
  formatting:              0.10,
  summary_quality:         0.05,
} as const;

// Compile-time guard — if weights don't sum to 1.0 the file won't run cleanly
const _WEIGHT_SUM = Object.values(W).reduce((a, b) => a + b, 0);
if (Math.abs(_WEIGHT_SUM - 1.0) > 0.001) {
  throw new Error(`[ats-engine] Weights must sum to 1.0, got ${_WEIGHT_SUM}`);
}

